import React, { useState, useEffect } from 'react';
import { Box, Container, Typography, Chip, Stack } from '@mui/material';
import VideoDubbingStudio from '../components/VideoDubbingStudio';
import { MovieFilter as DubIcon } from '@mui/icons-material';

const DubbingView = () => {
  const [userId, setUserId] = useState(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    setUserId(user.uid || user.userId);
  }, []);

  return (
    <Box sx={{ width: '100%', minHeight: '100vh', background: 'transparent', py: 4 }}>
      <Container maxWidth="xl">
        <Box sx={{ mb: 4 }}>
          <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 1 }}>
            <DubIcon sx={{ color: '#E8A020', fontSize: 32 }} />
            <Typography variant="h4" sx={{ fontWeight: 900, color: '#111111' }}>
              Video Dubbing Studio
            </Typography>
            <Chip label="PRO" size="small" sx={{ bgcolor: 'rgba(232, 160, 32, 0.2)', color: '#F5B844', border: '1px solid rgba(232, 160, 32, 0.3)', fontWeight: 800 }} />
          </Stack>
          <Typography variant="body1" sx={{ color: 'rgba(17, 17, 17, 0.5)', maxWidth: 600 }}>
            Neural video localization and dubbing. Translate your content across 50+ languages while maintaining voice identity.
          </Typography>
        </Box>
        {userId && <VideoDubbingStudio userId={userId} />}
      </Container>
    </Box>
  );
};

export default DubbingView;
