import React, { useState, useEffect } from 'react';
import { Box, Container, Typography, Chip, Stack } from '@mui/material';
import VoiceoverStudio from '../components/VoiceoverStudio';
import { MicExternalOn as MicIcon } from '@mui/icons-material';

const VoiceoverView = () => {
  const [userId, setUserId] = useState(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    setUserId(user.uid || user.userId);
  }, []);

  return (
    <Box sx={{ width: '100%', minHeight: '100vh', background: 'transparent', py: 4 }}>
      <Container maxWidth="xl">
        <Box sx={{ mb: 4 }}>
          <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 1 }}>
            <MicIcon sx={{ color: '#C47F10', fontSize: 32 }} />
            <Typography variant="h4" sx={{ fontWeight: 900, color: '#111111' }}>
              Professional Voiceovers
            </Typography>
            <Chip label="BETA" size="small" sx={{ bgcolor: 'rgba(232, 160, 32, 0.2)', color: '#F5B844', border: '1px solid rgba(232, 160, 32, 0.3)', fontWeight: 800 }} />
          </Stack>
          <Typography variant="body1" sx={{ color: 'rgba(17, 17, 17, 0.5)', maxWidth: 600 }}>
            Create multi-voice scripts for podcasts, commercials, and audiobooks. Precision control over neural narration.
          </Typography>
        </Box>
        {userId && <VoiceoverStudio userId={userId} />}
      </Container>
    </Box>
  );
};

export default VoiceoverView;
